window.docContents[46].resolve({"/Sorts/#sortsOverview":{"contents":"Sort constructors live in the Srt namespace and are all in the Env monad.\n\n#eval Env.runIO do\n  let b ← Srt.bool\n  let r ← Srt.real\n  let mapBoolReal ← b.arrayTo r\n  -- alternatively\n  let mapBoolReal' ← r.arrayFrom b\n  let ff ← Srt.finiteField 7\n  println! \"b := {b}\"\n  println! \"r := {r}\"\n  println! \"mapBoolReal := {mapBoolReal}\"\n  println! \"mapBoolReal' := {mapBoolReal'}\"\n  println! \"ff := {ff}\"\n\n\nb := Bool\nr := Real\nmapBoolReal := (Array Bool Real)\nmapBoolReal' := (Array Bool Real)\nff := (_ FiniteField 7)\n\n\n\n\n","context":"Cvc.lean -- High-Level API for CVC5","header":"3. Sorts","id":"/Sorts/#sortsOverview"}});